// Parsers returns kickr parsers, in the order they must run.
func Parsers(httpClient *http.Client) []engine.Parser[types.Repository] {
	return []engine.Parser[types.Repository]{
		// must be kept first (global parsing)
		ParserGit,
		ParserModules,

		ParserGlob,
		ParserHugo(httpClient),
		ParserGolang(httpClient),
		ParserNode,
		ParserTerraform,

		// must be kept last since it reads modules executables
		ParserHelm,
	}
}

